// Comparison function for qsort
int cmp(const void *a, const void *b) {
    return *(int*)a - *(int*)b;
}

// Function to calculate energy from difference d
long long energy(int d) {
    long long diff = d;
    return diff * (diff - 30) * (diff - 30);
}

