typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

static ll energy(ll d) {
    ll t = d - 30;
    return d * t * t;
}

int main(void) {
    int M, F;
    if (scanf("%d %d", &M, &F) != 2) return 0;

    ll *male = (ll *)malloc(sizeof(ll) * M);
    ll *female = (ll *)malloc(sizeof(ll) * F);
    if (!male || !female) return 0;

    for (int i = 0; i < M; i++) scanf("%lld", &male[i]);
    for (int i = 0; i < F; i++) scanf("%lld", &female[i]);

    qsort(male, M, sizeof(ll), cmp_ll);
    qsort(female, F, sizeof(ll), cmp_ll);

    int K = (M < F) ? M : F;

    /*
      Rearrangement principle:
      Since energy depends only on |bm-bw| and is increasing for larger |bm-bw|
      in the optimal pairing we maximize total absolute differences.
      This is achieved by pairing one side in ascending order with the other
      in descending order, choosing the best contiguous block when sizes differ.

      If M <= F:
        pair male[i] with female[s + (M-1-i)] for some s in [0, F-M]
      If F < M:
        pair male[s + i] with female[F-1-i] for some s in [0, M-F]

      We try all possible shifts.
    */

    ll ans = -1;

    if (M <= F) {
        for (int s = 0; s <= F - M; s++) {
            ll sum = 0;
            for (int i = 0; i < M; i++) {
                ll d = male[i] - female[s + (M - 1 - i)];
                if (d < 0) d = -d;
                sum += energy(d);
            }
            if (sum > ans) ans = sum;
        }
    } else {
        for (int s = 0; s <= M - F; s++) {
            ll sum = 0;
            for (int i = 0; i < F; i++) {
                ll d = male[s + i] - female[F - 1 - i];
                if (d < 0) d = -d;
                sum += energy(d);
            }
            if (sum > ans) ans = sum;
        }
    }

    printf("%lld\n", ans);

    free(male);
    free(female);
    return 0;
}

