import sys

def energy(diff: int) -> int:
    return diff * (diff - 30) * (diff - 30)

def hungarian_max(weight):
    # weight: n x m, n <= m, maximize total weight
    n = len(weight)
    m = len(weight[0]) if n > 0 else 0

    # Hungarian algorithm for minimization, so use costs = -weight
    u = [0] * (n + 1)
    v = [0] * (m + 1)
    p = [0] * (m + 1)
    way = [0] * (m + 1)

    INF = 10**30

    for i in range(1, n + 1):
        p[0] = i
        minv = [INF] * (m + 1)
        used = [False] * (m + 1)
        j0 = 0

        while True:
            used[j0] = True
            i0 = p[j0]
            delta = INF
            j1 = 0
            for j in range(1, m + 1):
                if not used[j]:
                    cur = -weight[i0 - 1][j - 1] - u[i0] - v[j]
                    if cur < minv[j]:
                        minv[j] = cur
                        way[j] = j0
                    if minv[j] < delta:
                        delta = minv[j]
                        j1 = j
            for j in range(m + 1):
                if used[j]:
                    u[p[j]] += delta
                    v[j] -= delta
                else:
                    minv[j] -= delta
            j0 = j1
            if p[j0] == 0:
                break

        while True:
            j1 = way[j0]
            p[j0] = p[j1]
            j0 = j1
            if j0 == 0:
                break

    match = [-1] * n
    for j in range(1, m + 1):
        if p[j] != 0:
            match[p[j] - 1] = j - 1

    total = 0
    for i in range(n):
        if match[i] != -1:
            total += weight[i][match[i]]
    return total

