public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int N = Integer.parseInt(firstLine[0]); // number of males
        int M = Integer.parseInt(firstLine[1]); // number of females

        long[] males = new long[N];
        long[] females = new long[M];

        String[] maleLine = br.readLine().split(" ");
        for (int i = 0; i < N; i++) {
            males[i] = Long.parseLong(maleLine[i]);
        }

        String[] femaleLine = br.readLine().split(" ");
        for (int i = 0; i < M; i++) {
            females[i] = Long.parseLong(femaleLine[i]);
        }

        // Sort both arrays
        Arrays.sort(males);
        Arrays.sort(females);

        // DP arrays: dp[i][j] = max energy using first i males and first j females
        long[][] dp = new long[N + 1][M + 1];

        // Initialize with very small values
        for (int i = 0; i <= N; i++) {
            Arrays.fill(dp[i], Long.MIN_VALUE / 2);
        }
        dp[0][0] = 0;

        for (int i = 0; i <= N; i++) {
            for (int j = 0; j <= M; j++) {
                if (dp[i][j] == Long.MIN_VALUE / 2) continue;

                // Skip this male
                if (i < N) {
                    dp[i + 1][j] = Math.max(dp[i + 1][j], dp[i][j]);
                }
                // Skip this female
                if (j < M) {
                    dp[i][j + 1] = Math.max(dp[i][j + 1], dp[i][j]);
                }
                // Pair current male with current female
                if (i < N && j < M) {
                    long diff = Math.abs(males[i] - females[j]);
                    long energy = diff * (diff - 30) * (diff - 30);
                    dp[i + 1][j + 1] = Math.max(dp[i + 1][j + 1], dp[i][j] + energy);
                }
            }
        }

        long answer = 0;
        // Answer is max over all states (we can leave some unpaired)
        for (int i = 0; i <= N; i++) {
            for (int j = 0; j <= M; j++) {
                answer = Math.max(answer, dp[i][j]);
            }
        }

        System.out.println(answer);
    }
}

