public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int M = sc.nextInt(), W = sc.nextInt();
            if (M == 0 && W == 0) break;
            long[] males = new long[M];
            long[] females = new long[W];
            for (int i = 0; i < M; i++) males[i] = sc.nextLong();
            for (int i = 0; i < W; i++) females[i] = sc.nextLong();

            int pairs = Math.min(M, W);
            // bitmask DP over females, pairing with first k males
            // dp[mask] = max energy using females in mask, paired with males[0..popcount(mask)-1]
            Arrays.sort(males);
            Arrays.sort(females);

            long[] dp = new long[1 << W];
            Arrays.fill(dp, Long.MIN_VALUE / 2);
            dp[0] = 0;

            for (int mask = 0; mask < (1 << W); mask++) {
                if (dp[mask] < Long.MIN_VALUE / 2 + 1) continue;
                int k = Integer.bitCount(mask);
                if (k >= pairs) continue;
                for (int j = 0; j < W; j++) {
                    if ((mask & (1 << j)) == 0) {
                        long d = Math.abs(males[k] - females[j]);
                        long energy = d * (d - 30) * (d - 30);
                        int nmask = mask | (1 << j);
                        if (dp[nmask] < dp[mask] + energy)
                            dp[nmask] = dp[mask] + energy;
                    }
                }
            }

            long ans = 0;
            for (int mask = 0; mask < (1 << W); mask++) {
                if (Integer.bitCount(mask) == pairs) ans = Math.max(ans, dp[mask]);
            }
            System.out.println(ans);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static long energy(long diff) {
        long x = Math.abs(diff);
        long y = x - 30;
        return x * y * y;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int m = fs.nextInt();
        int f = fs.nextInt();

        long[] males = new long[m];
        long[] females = new long[f];

        for (int i = 0; i < m; i++) males[i] = fs.nextLong();
        for (int i = 0; i < f; i++) females[i] = fs.nextLong();

        Arrays.sort(males);
        Arrays.sort(females);

        int n = Math.min(m, f);

        // DP on sorted sequences:
        // dp[i][j] = maximum energy using first i males and first j females
        // Transition:
        // - skip a male
        // - skip a female
        // - pair male i-1 with female j-1
        //
        // Space optimized to 1D.
        long[] prev = new long[f + 1];
        long[] cur = new long[f + 1];

        for (int i = 1; i <= m; i++) {
            cur[0] = 0;
            for (int j = 1; j <= f; j++) {
                long best = Math.max(prev[j], cur[j - 1]);
                best = Math.max(best, prev[j - 1] + energy(males[i - 1] - females[j - 1]));
                cur[j] = best;
            }
            long[] tmp = prev;
            prev = cur;
            cur = tmp;
        }

        System.out.println(prev[f]);
    }
